import { readFileSync } from "fs";

const nums = readFileSync(0, "utf8").trim().split(" ").map(Number);

// 比較関数を渡さないと文字列として並ぶ（"10" < "9" になる）
nums.sort((x, y) => x - y);
console.log(nums.join(" "));
